class FMCustomerRefGroup extends FMCustomerPage
{
    private str customerFullNameInternal;
    private ImageReference custImage;

}

Method.Source:
[SysAppField(tableMethodStr(FMCustomer,fullName ), "Customer name")]
public str customerFullName(str _value=customerFullNameInternal)
{
    customerFullNameInternal = _value;
    return customerFullNameInternal;
}

[SysAppField(fieldStr(FMCustomer, Image), "Customer image")]
public ImageReference customerImage(ImageReference _value=custImage)
{
    custImage = _value;
    return custImage;
}

public void populate(FMCustomer _customerTable)
{
    this.customerFullName(_customerTable.fullName());
    if (_customerTable.Image != conNull())
    {
        Image img = new Image();
        img.setData(_customerTable.Image);
        this.customerImage(ImageReference::constructForImage(img));
    }

    this.RecId(_customerTable.RecId);
}
